from app import db
from datetime import datetime, timezone

class Tenant(db.Model):
    __tablename__ = 'tenants'

    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)

    # 'single' or 'cooperative' 
    tenant_type = db.Column(db.String(20), default='single') 
    region = db.Column(db.String(100), nullable=True)
    registration_number = db.Column(db.String(100), nullable=True, unique=True)
    is_active = db.Column(db.Boolean, default=True)
    # The public read-only demo workspace. Its data is regenerated by `flask demo seed`.
    is_demo = db.Column(db.Boolean, nullable=False, default=False, server_default=db.false())
    created_at = db.Column(db.DateTime(timezone=True), default=lambda: datetime.now(timezone.utc))

    farms = db.relationship('Farm', backref='tenant', lazy=True)

    __table_args__ = (
        # At most one demo workspace.
        db.Index('uq_tenants_single_demo', 'is_demo', unique=True, postgresql_where=db.text('is_demo')),
    )